def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items):return '<ul>'+''.join(f'<li>{i}</li>' for i in items)+'</ul>'
def OL(items):return '<ol>'+''.join(f'<li>{i}</li>' for i in items)+'</ol>'
def LN(d,c='ln'):return f'<path d="{d}" class="{c}"/>'
def R(x,y,w,h,c='bx',r=3):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" class="{c}"/>'

# ---------- numbers (recomputed) ----------
def P(mA,pmin=0,pmax=10,lo=4,hi=20):return pmin+(mA-lo)/(hi-lo)*(pmax-pmin)
assert P(12)==5.0 and P(4)==0 and P(20)==10
assert 12/20*10==6.0      # wrong 0–20 mA scaling gives 6 bar instead of 5
assert abs(P(14)-6.25)<1e-9

